// Command thirdparty regenerates the Go-module part of THIRD_PARTY_LICENSES.
//
// Rule: a module is listed when at least one of its packages is linked into
// the shipped binary, i.e. it appears in `go list -deps ./cmd/den` for the
// release targets (linux, CGO off, amd64 and arm64). Modules that only appear
// in `go list -m all` (test helpers, pruned graph entries) are not shipped
// and need no notice. The text of every license, copying and patent file in
// a module's root is copied from the module cache, so nothing is guessed.
//
//	go run ./internal/tools/thirdparty            rewrite ../../THIRD_PARTY_LICENSES in place
//	go run ./internal/tools/thirdparty -check     exit 1 if the file is out of date
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"sort"
	"strings"
)

const (
	Begin = "<<<BEGIN GO MODULES: generated by `go run ./internal/tools/thirdparty`, do not edit by hand>>>"
	End   = "<<<END GO MODULES>>>"
)

var licenseName = regexp.MustCompile(`(?i)^(licen[cs]e|copying|notice|patents)(\.[a-z0-9]+)?$`)

// Module is one linked module and its license files.
type Module struct {
	Path, Version, Dir string
	Files              []string // base names
}

// Linked returns the modules linked into ./cmd/den, sorted by path.
func Linked(root string) ([]Module, error) {
	seen := map[string]Module{}
	for _, arch := range []string{"amd64", "arm64"} {
		cmd := exec.Command("go", "list", "-deps", "-f", "{{with .Module}}{{.Path}}\t{{.Version}}\t{{.Dir}}{{end}}", "./cmd/den")
		cmd.Dir = root
		cmd.Env = append(os.Environ(), "GOOS=linux", "GOARCH="+arch, "CGO_ENABLED=0")
		var stderr bytes.Buffer
		cmd.Stderr = &stderr
		out, err := cmd.Output()
		if err != nil {
			return nil, fmt.Errorf("go list: %v: %s", err, stderr.String())
		}
		for _, line := range strings.Split(string(out), "\n") {
			f := strings.Split(line, "\t")
			if len(f) != 3 || f[1] == "" { // empty version: the main module
				continue
			}
			seen[f[0]] = Module{Path: f[0], Version: f[1], Dir: f[2]}
		}
	}
	var mods []Module
	for _, m := range seen {
		ents, err := os.ReadDir(m.Dir)
		if err != nil {
			return nil, err
		}
		for _, e := range ents {
			if !e.IsDir() && licenseName.MatchString(e.Name()) {
				m.Files = append(m.Files, e.Name())
			}
		}
		sort.Strings(m.Files)
		mods = append(mods, m)
	}
	sort.Slice(mods, func(i, j int) bool { return mods[i].Path < mods[j].Path })
	return mods, nil
}

// Section renders the generated block, markers included.
func Section(mods []Module) (string, error) {
	var b strings.Builder
	b.WriteString(Begin + "\n\n")
	goroot := runtime.GOROOT()
	if out, err := exec.Command("go", "env", "GOROOT").Output(); err == nil {
		goroot = strings.TrimSpace(string(out))
	}
	std, err := os.ReadFile(filepath.Join(goroot, "LICENSE"))
	if err != nil {
		return "", err
	}
	b.WriteString("Go standard library (compiled into the binary by the Go toolchain)\nLicense: BSD-3-Clause, from $GOROOT/LICENSE\n\n")
	b.Write(bytes.TrimRight(std, "\n"))
	b.WriteString("\n\n")
	var missing []string
	for _, m := range mods {
		fmt.Fprintf(&b, "================================================================\nModule: %s\nVersion: %s\n", m.Path, m.Version)
		if len(m.Files) == 0 {
			missing = append(missing, m.Path)
			b.WriteString("License file: NONE FOUND in the module; not verified\n\n")
			continue
		}
		b.WriteString("License file(s): " + strings.Join(m.Files, ", ") + "\n")
		for _, f := range m.Files {
			text, err := os.ReadFile(filepath.Join(m.Dir, f))
			if err != nil {
				return "", err
			}
			fmt.Fprintf(&b, "\n--- %s ---\n\n%s\n", f, bytes.TrimRight(text, "\n"))
		}
		b.WriteString("\n")
	}
	b.WriteString(End + "\n")
	if len(missing) > 0 {
		return b.String(), fmt.Errorf("modules without a license file: %s", strings.Join(missing, ", "))
	}
	return b.String(), nil
}

// Splice replaces the marked block of doc with section.
func Splice(doc, section string) (string, error) {
	i := strings.Index(doc, Begin)
	j := strings.Index(doc, End)
	if i < 0 || j < i {
		return "", fmt.Errorf("markers not found")
	}
	return doc[:i] + section + strings.TrimPrefix(doc[j+len(End):], "\n"), nil
}

func main() {
	check := flag.Bool("check", false, "fail if THIRD_PARTY_LICENSES is out of date")
	root := flag.String("root", ".", "repository root")
	flag.Parse()
	path := filepath.Join(*root, "THIRD_PARTY_LICENSES")
	mods, err := Linked(*root)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	sec, serr := Section(mods)
	doc, err := os.ReadFile(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	out, err := Splice(string(doc), sec)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if *check {
		if out != string(doc) {
			fmt.Fprintln(os.Stderr, "THIRD_PARTY_LICENSES is out of date; run: go run ./internal/tools/thirdparty")
			os.Exit(1)
		}
	} else if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if serr != nil {
		fmt.Fprintln(os.Stderr, serr)
		os.Exit(1)
	}
}
